/**
 * loom: the derive behind the always-on subscription meter.
 *
 * Loom runs one pi instance over several subscription accounts, so
 * `SubscriptionUsagePoller` folds every account's windows into that instance's
 * flat window list with the account encoded in each id
 * (`@t3tools/shared/usageWindowId`). Upstream's pooled selectors group by
 * `account.driver` and key windows by `kind:id`, so the pi account is split
 * back into one synthetic account per encoded account before it is pooled —
 * otherwise Claude and Codex average into a single `pi` bar and every window
 * forms a single-member pool of its own.
 *
 * Pure: no atoms, no IO. The component memoises it on the limits slice.
 *
 * @module loom/subscriptionMeter
 */
import {
  ProviderDriverKind,
  type ServerProvider,
  type ServerProviderUsageWindow,
} from "@t3tools/contracts";
import {
  collectLimitAccounts,
  collectLimitPools,
  type LimitAccount,
  type LimitPool,
  type LimitPoolWindow,
  type LimitPresentations,
} from "@t3tools/shared/usageLimits";
import { decodeUsageWindowId } from "@t3tools/shared/usageWindowId";

/** The poller writes `providerInstanceId ?? providerName` into the account key. */
const DRIVER_OF: Record<string, ServerProvider["driver"]> = {
  claudeAgent: ProviderDriverKind.make("claudeAgent"),
  codex: ProviderDriverKind.make("codex"),
};

/** A window is loud at 80% used (warning) and at 100% (destructive). */
export const METER_WARNING_PERCENT = 80;
export const METER_DESTRUCTIVE_PERCENT = 100;

export type MeterTone = "quiet" | "warning" | "destructive";

export function meterTone(usedPercent: number): MeterTone {
  if (usedPercent >= METER_DESTRUCTIVE_PERCENT) return "destructive";
  if (usedPercent >= METER_WARNING_PERCENT) return "warning";
  return "quiet";
}

/**
 * Split the pi instance's account-encoded windows into poolable accounts. Hub
 * and natively reported accounts pass through untouched.
 */
export function splitLoomPiAccount(account: LimitAccount): readonly LimitAccount[] {
  if (account.driver !== "pi") return [account];
  const byAccount = new Map<string, ServerProviderUsageWindow[]>();
  for (const window of account.limits.windows) {
    const identity = decodeUsageWindowId(window.id);
    if (!identity) continue; // a natively emitted window is not an account row
    const key = `${identity.accountKey}:${identity.accountLabel ?? ""}`;
    // Account-independent id: sibling accounts must share a key to pool.
    const id = identity.scope ? `${identity.kind}:${identity.scope}` : identity.kind;
    const windows = byAccount.get(key) ?? [];
    windows.push({ ...window, id });
    byAccount.set(key, windows);
  }
  return [...byAccount].map(([key, windows]) => ({
    ...account,
    key: `pi:${key}`,
    driver: DRIVER_OF[key.split(":")[0]!] ?? account.driver,
    displayName: key.split(":")[1] || null,
    limits: { ...account.limits, windows },
  }));
}

/** Every connected environment's accounts, split and pooled by driver. */
export function meterPools(presentations: LimitPresentations, now: number): readonly LimitPool[] {
  return collectLimitPools(collectLimitAccounts(presentations).flatMap(splitLoomPiAccount), now);
}

/** How often the countdown moves, and the bucket the derive is cached in. */
export const METER_TICK_MS = 30_000;

export interface MeterPoolView {
  readonly pool: LimitPool;
  /** The tick this pool last came from a live reading. */
  readonly readAt: number;
  readonly stale: boolean;
}

/** One entry, shared by the footer meter and its header chip: they derive the same pools. */
let memo: {
  readonly key: string;
  readonly now: number;
  readonly pools: readonly LimitPool[];
} | null = null;
const held = new Map<
  ServerProvider["driver"],
  { readonly pool: LimitPool; readonly readAt: number }
>();

/**
 * The pools to draw, each marked live or stale.
 *
 * Provider limits are runtime snapshot state: a reconnect, a server restart, or
 * a provider republishing its snapshot delivers a `serverConfig` with none
 * until the poller publishes again — and it goes per provider rather than all
 * at once (a hub's snapshot survives what drops an instance's windows). The
 * meter is on screen permanently, so each driver's last reading is held and
 * marked stale rather than blinking out; nothing is drawn only when there has
 * never been a reading, and a reload starts empty again.
 *
 * Cached on the limits slice and the tick, because the presentations atom
 * updates on every `serverConfig` change and the sidebar is always mounted.
 */
export function readMeter(
  presentations: LimitPresentations,
  now: number,
): readonly MeterPoolView[] {
  const key = `${limitsFingerprint(presentations)}|${Math.floor(now / METER_TICK_MS)}`;
  if (memo?.key !== key) memo = { key, now, pools: meterPools(presentations, now) };
  const live = new Set(memo.pools.map((pool) => pool.driver));
  // Held in first-seen order, so a bar never jumps position between readings.
  for (const pool of memo.pools) held.set(pool.driver, { pool, readAt: memo.now });
  return [...held].map(([driver, entry]) => ({ ...entry, stale: !live.has(driver) }));
}

/**
 * Identity of the limits slice of the presentations map. The atom updates on
 * every `serverConfig` change and the meter is always on screen, so the derive
 * runs only when a reading actually lands.
 */
export function limitsFingerprint(presentations: LimitPresentations): string {
  const parts: string[] = [];
  for (const [environmentId, presentation] of presentations) {
    for (const provider of presentation.serverConfig?.providers ?? []) {
      if (provider.usageLimits)
        parts.push(`${provider.instanceId}@${provider.usageLimits.checkedAt}`);
    }
    for (const source of presentation.serverConfig?.usageLimitSources ?? []) {
      parts.push(`${environmentId}/${source.id}@${source.checkedAt}`);
    }
  }
  return parts.join("|");
}

/** Labels come from the window kind: a pooled label is inherited from whichever member was first. */
const KIND_LABEL: Record<ServerProviderUsageWindow["kind"], string> = {
  session: "Session",
  weekly: "Weekly",
  monthly: "Monthly",
  other: "Other",
};

/**
 * A pooled window's label. `LimitPoolWindow.label` is inherited from whichever
 * member landed first — for loom's split windows that is one account's own
 * label (`carl3@ 5-hour`) — so the kind names the row, and only the per-model
 * carve-out's scope is taken from the id (loom's `kind:scope`) or from the
 * inherited label (a hub's `Weekly · Fable`).
 */
export function poolWindowLabel(window: LimitPoolWindow): string {
  const scope = window.id.split(":")[1] ?? window.label.split(" · ")[1];
  return scope ? `${KIND_LABEL[window.kind]} · ${scope}` : KIND_LABEL[window.kind];
}

/**
 * The number the bar shows: the account-wide session window. Scoped carve-outs
 * are weekly by construction, so they never reach the headline. A subscription
 * reported both natively and through a hub keys its session window twice, so
 * the widest pool wins and the louder one breaks the tie.
 */
export function headlinePoolWindow(pool: LimitPool): LimitPoolWindow | undefined {
  return [...pool.windows]
    .filter((window) => window.kind === "session")
    .sort(
      (left, right) =>
        right.members.length - left.members.length || right.usedPercent - left.usedPercent,
    )[0];
}

/** Tone follows the loudest window, so a weekly carve-out can drive the highlight. */
export function poolTone(pool: LimitPool): MeterTone {
  return meterTone(Math.max(0, ...pool.windows.map((window) => window.usedPercent)));
}

/**
 * loom: the always-on subscription meter — one bar per pooled subscription in
 * the sidebar footer, mirrored as a chip in the chat header while the sidebar
 * is closed.
 *
 * It reads the presentations atom every client already subscribes to, so it
 * adds no RPC and no wire traffic. Tier 4 state throughout
 * (`docs/architecture/loom-ui-state-tiers.md`): the pools are derived, the only
 * mutable state is a 30-second countdown tick, and the header chip *reads*
 * sidebar visibility without ever writing it.
 *
 * @module loom/SubscriptionMeter
 */
import { useAtomValue } from "@effect/atom-react";
import { useNavigate } from "@tanstack/react-router";
import {
  formatDuration,
  type LimitPace,
  type LimitPool,
  type LimitPoolWindow,
} from "@t3tools/shared/usageLimits";
import { memo, useEffect, useState } from "react";

import { ProviderInstanceIcon } from "~/components/chat/ProviderInstanceIcon";
import { getDriverOption } from "~/components/settings/providerDriverMeta";
import { Popover, PopoverPopup, PopoverTrigger } from "~/components/ui/popover";
import { useSidebarVisibility } from "~/components/ui/sidebar";
import { AccountName } from "~/components/usage/UsageLimitsPooled";
import { cn } from "~/lib/utils";
import { environmentPresentations } from "~/state/presentation";
import {
  headlinePoolWindow,
  METER_TICK_MS,
  type MeterPoolView,
  meterTone,
  type MeterTone,
  poolTone,
  poolWindowLabel,
  readMeter,
} from "./subscriptionMeter";

const LABEL_TONE: Record<MeterTone, string> = {
  quiet: "text-muted-foreground",
  warning: "text-warning",
  destructive: "text-destructive",
};

const BAR_TONE: Record<MeterTone, string> = {
  quiet: "bg-muted-foreground/50",
  warning: "bg-warning",
  destructive: "bg-destructive",
};

const PACE_LABEL: Record<LimitPace, string> = {
  ahead: "ahead of pace",
  on: "on pace",
  under: "under pace",
};

/** The pools to draw, each marked live or stale, and the countdown clock. */
function useMeterReading(): { readonly views: readonly MeterPoolView[]; readonly now: number } {
  const presentations = useAtomValue(environmentPresentations.presentationsAtom);
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), METER_TICK_MS);
    return () => window.clearInterval(id);
  }, []);
  return { views: readMeter(presentations, now), now };
}

function percentOf(pool: LimitPool): number {
  return headlinePoolWindow(pool)?.usedPercent ?? 0;
}

function driverLabel(pool: LimitPool): string {
  return getDriverOption(pool.driver)?.label ?? String(pool.driver);
}

/** One pooled window: what is spent, the pace, and every account's own share. */
function WindowRow({ window }: { readonly window: LimitPoolWindow }) {
  // Each row carries its own tone; the bar outside takes the loudest of them.
  const tone = meterTone(window.usedPercent);
  return (
    <div className="flex flex-col gap-1">
      <div className="flex items-baseline justify-between gap-3 text-[11px] leading-4">
        <span className="text-muted-foreground/70">{poolWindowLabel(window)} pool</span>
        <span className="tabular-nums text-muted-foreground/80">
          {window.usedPercent}% used{window.pace ? ` · ${PACE_LABEL[window.pace]}` : ""}
        </span>
      </div>
      <div
        className="h-1.5 w-full overflow-hidden rounded-full bg-muted/60"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={window.usedPercent}
        aria-label={`${poolWindowLabel(window)} pool usage`}
      >
        <div
          className={cn("h-full rounded-full", BAR_TONE[tone])}
          style={{ width: `${window.usedPercent}%` }}
        />
      </div>
      {window.members.length > 1 ? (
        <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-[11px] text-muted-foreground/70">
          {window.members.map((member) => (
            <span key={member.account.key} className="inline-flex items-center gap-1">
              <AccountName account={member.account} className="max-w-24 truncate" />
              <span className="tabular-nums">{Math.round(member.window.usedPercent)}%</span>
            </span>
          ))}
        </div>
      ) : null}
    </div>
  );
}

/** The pooled breakdown: every window, then the resets in the order they land. */
function MeterPopover({
  pool,
  now,
  stale,
  readAt,
}: {
  readonly pool: LimitPool;
  readonly now: number;
  readonly stale: boolean;
  readonly readAt: number;
}) {
  const plan = pool.accounts.every((entry) => entry.plan === pool.accounts[0]?.plan)
    ? pool.accounts[0]?.plan
    : undefined;
  const ladder = (headlinePoolWindow(pool)?.resets ?? []).filter(
    (reset) => reset.restoresPercent > 0,
  );
  return (
    <div className="flex w-72 max-w-[calc(100vw-3rem)] flex-col gap-2.5 p-3">
      <div className="flex items-baseline justify-between gap-3">
        <span className="text-xs font-medium text-foreground">
          {driverLabel(pool)} · {pool.accounts.length}{" "}
          {pool.accounts.length === 1 ? "account" : "accounts"}
        </span>
        {plan ? <span className="text-[11px] text-muted-foreground/60">{plan}</span> : null}
      </div>
      {pool.windows.map((window) => (
        <WindowRow key={`${window.kind}:${window.id}`} window={window} />
      ))}
      {ladder.length > 0 ? (
        <div className="flex flex-col gap-0.5 border-t border-border/60 pt-2 text-[11px] text-muted-foreground/60">
          {ladder.slice(0, 3).map((reset) => (
            <span key={reset.member.account.key} className="flex items-center gap-1 tabular-nums">
              ↻ <AccountName account={reset.member.account} className="max-w-24 truncate" />
              {reset.at <= now ? "now" : formatDuration(reset.at - now)} · +{reset.restoresPercent}%
              of pool
            </span>
          ))}
        </div>
      ) : null}
      <span className="text-[11px] text-muted-foreground/50">
        {stale
          ? `Not reported since the last read ${formatDuration(now - readAt)} ago.`
          : `Pooled subscription limits as last reported to ${driverLabel(pool)}.`}
      </span>
    </div>
  );
}

/** Bar, chip, and their shared popover; clicking either opens the Usage page. */
function MeterControl({
  view: { pool, stale, readAt },
  now,
  compact,
}: {
  readonly view: MeterPoolView;
  readonly now: number;
  readonly compact: boolean;
}) {
  const navigate = useNavigate();
  const tone = poolTone(pool);
  const percent = percentOf(pool);
  const label = driverLabel(pool);
  const open = () => void navigate({ to: "/usage" });
  const ariaLabel = `${label} subscription usage ${percent}% used across ${pool.accounts.length} ${
    pool.accounts.length === 1 ? "account" : "accounts"
  }${stale ? ", not reported recently" : ""}`;
  return (
    <Popover>
      <PopoverTrigger
        openOnHover
        delay={150}
        closeDelay={0}
        render={
          <button
            type="button"
            onClick={open}
            aria-label={ariaLabel}
            className={cn(
              "flex min-w-0 items-center rounded-md outline-none transition-colors hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background",
              compact
                ? "h-6 gap-1 border border-border/60 px-1.5 text-[11px]"
                : "flex-[1_1_calc(50%-0.5rem)] flex-col gap-1.5 px-1 py-0.5 text-left",
              LABEL_TONE[tone],
              stale && "opacity-50",
            )}
          />
        }
      >
        {compact ? (
          <>
            <ProviderInstanceIcon
              driverKind={pool.driver}
              displayName={label}
              indicatorBackground="var(--background)"
              className="size-3.5"
              iconClassName="size-3 text-foreground/80"
            />
            <span className="shrink-0 font-medium tabular-nums">{percent}%</span>
          </>
        ) : (
          <>
            <span className="flex w-full items-baseline justify-between gap-2 text-xs font-medium">
              <span className="truncate">{label}</span>
              <span className="shrink-0 tabular-nums">{percent}%</span>
            </span>
            <span
              className="h-1 w-full overflow-hidden rounded-full bg-muted/60"
              role="progressbar"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={percent}
            >
              <span
                className={cn("block h-full rounded-full", BAR_TONE[tone])}
                style={{ width: `${percent}%` }}
              />
            </span>
          </>
        )}
      </PopoverTrigger>
      <PopoverPopup tooltipStyle side="top" align="start" className="w-72 max-w-none p-0">
        <MeterPopover pool={pool} now={now} stale={stale} readAt={readAt} />
      </PopoverPopup>
    </Popover>
  );
}

/** One bar per pooled subscription, for the sidebar footer. */
export const SubscriptionMeter = memo(function SubscriptionMeter() {
  const { views, now } = useMeterReading();
  if (views.length === 0) return null;
  return (
    <div className="flex flex-wrap gap-x-4 gap-y-2 p-1">
      {views.map((view) => (
        <MeterControl key={view.pool.driver} view={view} now={now} compact={false} />
      ))}
    </div>
  );
});

function SubscriptionMeterChipRow() {
  const { views, now } = useMeterReading();
  return (
    <div className="flex shrink-0 items-center gap-1.5">
      {views.map((view) => (
        <MeterControl key={view.pool.driver} view={view} now={now} compact />
      ))}
    </div>
  );
}

/**
 * The same meter in the chat header, shown only while the sidebar is closed —
 * an offcanvas sidebar takes its footer to zero width. Read-only: an indicator
 * must never nudge the sidebar open or closed.
 */
export const SubscriptionMeterChip = memo(function SubscriptionMeterChip() {
  const sidebarVisible = useSidebarVisibility();
  return sidebarVisible ? null : <SubscriptionMeterChipRow />;
});

/**
 * Selection and pace maths for the provider limits view, shared by web and
 * mobile so both agree on which providers show, what "ahead of pace" means,
 * and how a reset is phrased.
 *
 * @module usageLimits
 */
import {
  type EnvironmentId,
  type UsageLimitsReport,
  type ProviderInstanceId,
  type ProviderConsumeResetCreditInput,
  type ServerProviderSlashCommand,
  isProviderAvailable,
  type ServerProvider,
  type ServerProviderUsageLimits,
  type ServerProviderUsageWindow,
  type UsageLimitSourceSnapshots,
} from "@t3tools/contracts";

import * as DateTime from "effect/DateTime";

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/**
 * Providers that belong on the Limits view: enabled, installed, and one whose
 * driver reports subscription usage at all. A driver with no notion of usage
 * never sets `usageLimits`, so it has no row rather than an empty one.
 */
export function providersWithLimits(
  providers: readonly ServerProvider[],
): readonly ServerProvider[] {
  return providers.filter(
    (provider) =>
      provider.enabled &&
      provider.installed &&
      isProviderAvailable(provider) &&
      provider.usageLimits !== undefined,
  );
}

export type LimitPresentations = ReadonlyMap<
  EnvironmentId,
  {
    readonly entry: { readonly target: { readonly label: string } };
    readonly serverConfig: {
      readonly providers?: readonly ServerProvider[] | undefined;
      readonly usageLimitSources?: UsageLimitSourceSnapshots | undefined;
    } | null;
  }
>;

function accountKey(driver: ServerProvider["driver"], email: string | undefined): string | null {
  const normalizedEmail = email?.trim().toLowerCase();
  return normalizedEmail ? `${driver}:${normalizedEmail}` : null;
}

/**
 * One subscription account as the pooled views see it, whichever way it was
 * reported. The same email signed in natively on two environments, or reported
 * by a hub as well as natively, is one account: its quota is one bucket, so
